/** Explicit worker capabilities; mail, approvals, documents and outcomes are never writable here. */
final class LifeOpportunityAgentAccess {
 public const PERMISSIONS=['research:claim','research:execute','research:propose','daily:queue','context:use','tracking:read','company:read','contact:read','research:read','opportunity:read','pipeline:read','status:read','company:write','contact:write','research:write','opportunity:write','pipeline:write','status:write'];
 private const TYPES=['company'=>'companies','contact'=>'contacts','research'=>'research','opportunity'=>'opportunities','pipeline'=>'pipelines','status'=>'statuses'];
 public function __construct(private LifeAyoOS $os,private mixed $clock=null,private mixed $transport=null){if(!$os->store->db->inTransaction())$os->store->db->exec(file_get_contents(__DIR__.'/migrations/opportunity-agent-access.sql'));}
 private function time():int{return$this->clock?($this->clock)():time();}private function at():string{return gmdate('Y-m-d\TH:i:s\Z',$this->time());}private function day():string{return(new DateTimeImmutable('@'.$this->time()))->setTimezone(new DateTimeZone('Africa/Lagos'))->format('Y-m-d');}
 private function transaction(callable$f):mixed{$db=$this->os->store->db;$own=!$db->inTransaction();if($own)$db->beginTransaction();try{$r=$f();if($own)$db->commit();return$r;}catch(Throwable$e){if($own&&$db->inTransaction())$db->rollBack();throw$e;}}
 public static function validate(mixed$permissions):array {if(!is_array($permissions)||!array_is_list($permissions)||!$permissions||count($permissions)>count(self::PERMISSIONS))throw new LifeError('Choose explicit worker permissions.');foreach($permissions as$p)if(!is_string($p)||!in_array($p,self::PERMISSIONS,true))throw new LifeError('This permission cannot be granted to research workers.',403);return array_values(array_unique($permissions));}
 public static function permissions(PDO$db,string$hash):array {try{$q=$db->prepare('SELECT permissions_json FROM life_opportunity_agent_permissions WHERE token_hash=?');$q->execute([$hash]);$raw=$q->fetchColumn();}catch(PDOException){$raw=false;}return$raw?json_decode($raw,true,32,JSON_THROW_ON_ERROR):['research:claim','research:propose'];}
 public static function requireScope(PDO$db,array$auth,string$scope):void{if(!in_array($scope,self::permissions($db,$auth['token_hash']),true))throw new LifeError('This worker was not granted '.$scope.'.',403);}
 public function authenticate(string$authorization):array {if(!preg_match('/^Bearer ([a-f0-9]{64})$/D',$authorization,$m))throw new LifeError('Worker authentication required.',401);$q=$this->os->store->db->prepare('SELECT * FROM life_opportunity_agent_tokens WHERE token_hash=? AND tenant_id=? AND revoked_at=? AND expires_at>?');$q->execute([hash('sha256',$m[1]),$this->os->store->tenantId,'',$this->at()]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new LifeError('Worker connection is invalid or expired.',401);return$r;}
 private function authorize(string$authorization,string$scope):array{$a=$this->authenticate($authorization);self::requireScope($this->os->store->db,$a,$scope);return$a;}
 private static function normal(string$v):string{return preg_replace('/\s+/u',' ',mb_strtolower(trim($v)));}
 private static function website(string$v):string{if($v==='')return'';$u=parse_url($v);return strtolower(preg_replace('/^www\./','',$u['host']??'')).rtrim($u['path']??'','/');}
 private static function publicSource(string$url):bool{if($url==='')return false;try{LifeApplications::url($url);}catch(LifeError){return false;}$host=strtolower(parse_url($url,PHP_URL_HOST)??'');return!in_array($host,['mail.google.com','inbox.google.com','outlook.live.com','outlook.office.com','mail.yahoo.com','mail.proton.me','proton.me'],true);}
 public function read(string$authorization,array$args):array {$auth=$this->authenticate($authorization);$kind=$args['collection']??'';if(!isset(self::TYPES[$kind]))throw new LifeError('Choose a tracking collection.');$granted=self::permissions($this->os->store->db,$auth['token_hash']);if(!in_array('tracking:read',$granted,true)&&!in_array($kind.':read',$granted,true))throw new LifeError('This tracking read was not approved.',403);$limit=$args['limit']??100;$offset=$args['offset']??0;if(!is_int($limit)||$limit<1||$limit>200||!is_int($offset)||$offset<0)throw new LifeError('Choose a bounded tracking page.');$data=$this->os->read();$rows=$data['state'][self::TYPES[$kind]]??[];$fields=match($kind){'company'=>['id','name','industry','website','about','recentNews','problem','fit','linkedin','socialUrl'],'contact'=>['id','companyId','name','role','email','sourceUrl','linkedin'],'opportunity'=>['id','companyId','pipeline','title','stage','followUpDate','description'],'research'=>['id','opportunityId','kind','category','body','sourceUrl'],default=>['id','name']};if($kind==='research')$rows=array_filter($rows,fn($r)=>($r['category']??'company')==='company'&&self::publicSource($r['sourceUrl']??''));return['workspaceId'=>$data['workspaceId'],'version'=>$data['version'],'records'=>array_map(fn($r)=>array_intersect_key($r,array_flip($fields)),array_slice(array_values($rows),$offset,$limit)),'nextOffset'=>count($rows)>$offset+$limit?$offset+$limit:null];}
 private function writeArgs(string$kind,array$args,array$state):array {
  $allowed=match($kind){'company'=>['id','name','industry','website','about','recentNews','problem','fit','linkedin','socialUrl'],'contact'=>['id','companyId','name','role','email','sourceUrl','linkedin','notes'],'research'=>['id','opportunityId','kind','category','body','sourceUrl'],'opportunity'=>['id','companyId','pipeline','title','stage','followUpDate','description','notes'],default=>['id','name']};foreach(array_keys($args)as$key)if(!in_array($key,$allowed,true)&&$key!=='emailEvidence')throw new LifeError('Workers cannot change '.$key.'.',403);$out=array_intersect_key($args,array_flip($allowed));
  if($kind==='research'){$old=isset($out['id'])?LifeApplications::find($state,'research',$out['id']):null;if($old&&(($old['category']??'company')!=='company'||!self::publicSource($old['sourceUrl']??'')))throw new LifeError('Workers cannot edit personal notes, activity or mail research.',403);if(($out['category']??$old['category']??'company')!=='company'||!self::publicSource($out['sourceUrl']??$old['sourceUrl']??''))throw new LifeError('Workers may write sourced public company research only.',403);$out['category']='company';}
  if($kind==='status'&&isset($out['id'])){$oldStatus=LifeApplications::find($state,'statuses',$out['id']);if(!in_array(self::normal($oldStatus['name']),['researching','needs research','needs review','qualified','to contact','on hold','waiting for information','prospect'],true))throw new LifeError('Workers cannot rename verified or owner-defined outcome labels.',403);}
  if($kind==='status'&&!in_array(self::normal($out['name']??''),['researching','needs research','needs review','qualified','to contact','on hold','waiting for information','prospect'],true))throw new LifeError('Workers may create preparation labels only.',403);
  if($kind==='opportunity'){$old=isset($out['id'])?LifeApplications::find($state,'opportunities',$out['id']):null;if(isset($out['stage'])&&!in_array($out['stage'],['researched','ready','pending','incomplete','paused'],true))throw new LifeError('Workers cannot infer application progress or outcomes.',403);if($old&&isset($out['stage'])&&$out['stage']!==$old['stage']&&!in_array($old['stage'],['researched','ready','pending','incomplete','paused'],true))throw new LifeError('Preserve the verified application status.',403);}
  if($kind==='contact'&&($out['email']??'')!==''&&((($out['sourceUrl']??'')==='')||!str_contains((string)($args['emailEvidence']??''),$out['email'])))throw new LifeError('Published email evidence is required.',422);
  if(in_array($kind,['pipeline','status'],true)&&preg_match('/accepted|offer|won|revenue|paid|sent|submitted|interview|replied/i',$out['name']??''))throw new LifeError('Workers cannot create labels that assert progress or outcomes.',403);
  return$out;
 }
 private function duplicate(string$kind,array$args,array$state):?array{if(!empty($args['id']))return null;$rows=$state[self::TYPES[$kind]]??[];$matches=array_values(array_filter($rows,function($r)use($kind,$args){return match($kind){'company'=>(!empty($args['website'])&&self::website($r['website']??'')===self::website($args['website']))||self::normal($r['name'])===self::normal($args['name']??''),'contact'=>($r['companyId']??'')===($args['companyId']??'')&&((!empty($args['email'])&&strtolower($r['email']??'')===strtolower($args['email']))||self::normal($r['name'])===self::normal($args['name']??'')),'opportunity'=>($r['companyId']??'')===($args['companyId']??'')&&($r['pipeline']??'')===($args['pipeline']??'')&&self::normal($r['title'])===self::normal($args['title']??''),'research'=>($r['opportunityId']??'')===($args['opportunityId']??'')&&($r['sourceUrl']??'')===($args['sourceUrl']??'')&&self::normal($r['body'])===self::normal($args['body']??''),default=>self::normal($r['name'])===self::normal($args['name']??'')};}));if(count($matches)>1)throw new LifeError('Ambiguous duplicate records need owner review.',409);if($kind==='company'&&isset($matches[0])&&!empty($args['website'])&&!empty($matches[0]['website'])){$oldHost=strtolower(preg_replace('/^www\./','',parse_url($matches[0]['website'],PHP_URL_HOST)??''));$newHost=strtolower(preg_replace('/^www\./','',parse_url($args['website'],PHP_URL_HOST)??''));if($oldHost!==$newHost)throw new LifeError('This company name matches a different website. Owner review is required.',409);}return$matches[0]??null;}
 public function write(string$authorization,array$input):array {
  $auth=$this->authenticate($authorization);$operation=$input['operation']??'';if(!is_string($operation)||!preg_match('/^(company|contact|research|opportunity|pipeline|status)\.save$/D',$operation,$m))throw new LifeError('This operation is unavailable to workers.',403);$kind=$m[1];self::requireScope($this->os->store->db,$auth,$kind.':write');$args=$input['args']??null;if(!is_array($args)||array_is_list($args))throw new LifeError('Use structured record fields.');$requestId=LifeStore::text($input['requestId']??'',100,true);if(!preg_match('/^[a-zA-Z0-9_-]{8,100}$/D',$requestId))throw new LifeError('Use a stable write request identifier.');$key=hash('sha256',$this->os->store->tenantId.':'.$requestId);$fingerprint=hash('sha256',json_encode([$auth['token_hash'],$operation,$args,$input['version']??null],JSON_THROW_ON_ERROR));
  return$this->transaction(function()use($auth,$operation,$kind,$args,$key,$fingerprint,$input){$db=$this->os->store->db;$q=$db->prepare('SELECT * FROM life_opportunity_agent_receipts WHERE id=?');$q->execute([$key]);$receipt=$q->fetch(PDO::FETCH_ASSOC);if($receipt){if(!hash_equals($receipt['fingerprint'],$fingerprint))throw new LifeError('This write identifier already belongs to a different change.',409);return json_decode($receipt['response_json'],true,64,JSON_THROW_ON_ERROR)+['duplicateRequest'=>true];}$snapshot=$this->os->read();if(!is_int($input['version']??null)||$input['version']!==$snapshot['version'])throw new LifeError('Tracking changed. Read the latest version before writing.',409);$safe=$this->writeArgs($kind,$args,$snapshot['state']);$duplicate=$this->duplicate($kind,$safe,$snapshot['state']);$before=isset($safe['id'])?LifeApplications::find($snapshot['state'],self::TYPES[$kind],$safe['id']):($duplicate??null);if($duplicate){$after=$duplicate;$result=['workspaceId'=>$snapshot['workspaceId'],'version'=>$snapshot['version'],'recordId'=>$duplicate['id'],'deduplicated'=>true];}else{$saved=$this->os->mutate($snapshot['version'],$operation,$safe,'worker:'.substr($auth['token_hash'],0,12));$after=LifeApplications::find($saved['state'],self::TYPES[$kind],$saved['recordId']);$result=['workspaceId'=>$saved['workspaceId'],'version'=>$saved['version'],'recordId'=>$saved['recordId'],'deduplicated'=>false];}$audit=LifeStore::id();$db->prepare('INSERT INTO life_opportunity_agent_audit VALUES (?,?,?,?,?,?,?,?)')->execute([$audit,$this->os->store->tenantId,$auth['token_hash'],$operation,$result['recordId'],json_encode($before,JSON_THROW_ON_ERROR),json_encode($after,JSON_THROW_ON_ERROR),$this->at()]);$result['auditId']=$audit;$db->prepare('INSERT INTO life_opportunity_agent_receipts VALUES (?,?,?,?,?)')->execute([$key,$this->os->store->tenantId,$fingerprint,json_encode($result,JSON_THROW_ON_ERROR),$this->at()]);return$result;});
 }
 public static function jobPolicy(PDO$db,string$id):array{$q=$db->prepare('SELECT policy_json FROM life_opportunity_agent_job_policy WHERE job_id=?');$q->execute([$id]);$raw=$q->fetchColumn();return$raw?json_decode($raw,true,32,JSON_THROW_ON_ERROR):['autoApply'=>false,'usePrivateContext'=>false,'opportunityId'=>''];}
 public static function dailyPlan():array {return[
 ['pipeline'=>'nysc','query'=>'NYSC Lagos/Nigeria: technology consulting and digital transformation first, then healthtech, enterprise AI, edtech/govtech, venture builders and product startups. Seek research, business analysis, implementation, operations or product contributions, not only design vacancies.'],
 ['pipeline'=>'freelance','query'=>'Nigerian paying clients: B2B SaaS, software agencies, AI, enterprise software and healthtech. Research dated buying signals, accessible founders/product leads and a defined product/UX service opportunity.'],
 ['pipeline'=>'freelance','query'=>'International remote paying clients: B2B SaaS, software agencies, AI and healthtech. Verify geographic eligibility and current buying signals. Consider 2–30-person startups and recent2–9-month funding as heuristics, not eligibility rules.'],
 ['pipeline'=>'career','query'=>'Relevant local and international roles spanning Product, Technology, Healthcare, AI and Business: consulting, business analysis, product strategy/operations, digital transformation and implementation. Verify location, eligibility and open status.'],
 ['pipeline'=>'ai-testing','query'=>'AI evaluation/testing niches: human-AI interaction, design/UX evaluation, healthcare or lab workflow subject matter, qualitative research and generalist evaluation. Verify current applications and eligible geography. Do not infer acceptance from profiles or invites.']
 ];}
 public function daily(string$authorization,array$args=[]):array {$auth=$this->authorize($authorization,'daily:queue');return$this->transaction(function()use($auth){$db=$this->os->store->db;$key=hash('sha256',$this->os->store->tenantId.':'.$this->day());$q=$db->prepare('SELECT jobs_json FROM life_opportunity_agent_daily WHERE id=?');$q->execute([$key]);$old=$q->fetchColumn();if($old)return['day'=>$this->day(),'jobs'=>json_decode($old,true),'duplicate'=>true,'maxProspects'=>25];$q=$db->prepare('SELECT COUNT(*) FROM life_opportunity_agent_jobs WHERE tenant_id=? AND status IN (?,?)');$q->execute([$auth['tenant_id'],'queued','leased']);if((int)$q->fetchColumn()+5>20)throw new LifeError('Finish existing research jobs before queuing the daily batch.',429);$jobs=[];foreach(self::dailyPlan()as$task){$id=LifeStore::id();$db->prepare('INSERT INTO life_opportunity_agent_jobs VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$auth['tenant_id'],$task['pipeline'],$task['query'],5,'queued',$this->at(),'','',0,'','','','']);$db->prepare('INSERT INTO life_opportunity_agent_job_policy VALUES (?,?)')->execute([$id,json_encode(['autoApply'=>true,'usePrivateContext'=>false,'opportunityId'=>''],JSON_THROW_ON_ERROR)]);$jobs[]=['id'=>$id,'pipeline'=>$task['pipeline'],'status'=>'queued','maxProspects'=>5,'autoApply'=>true];}$db->prepare('INSERT INTO life_opportunity_agent_daily VALUES (?,?,?,?)')->execute([$key,$auth['tenant_id'],$this->day(),json_encode($jobs,JSON_THROW_ON_ERROR)]);return['day'=>$this->day(),'jobs'=>$jobs,'duplicate'=>false,'maxProspects'=>25];});}
 private function lease(array$auth,array$args):array {$id=LifeApplications::id($args['jobId']??'');$lease=$args['leaseToken']??'';if(!is_string($lease)||!preg_match('/^[a-f0-9]{64}$/D',$lease))throw new LifeError('An active research lease is required.',403);$q=$this->os->store->db->prepare('SELECT * FROM life_opportunity_agent_jobs WHERE id=? AND tenant_id=?');$q->execute([$id,$auth['tenant_id']]);$job=$q->fetch(PDO::FETCH_ASSOC);if(!$job)throw new LifeError('Research job unavailable.',404);if(!hash_equals($job['lease_hash'],hash('sha256',$lease)))throw new LifeError('Research lease is invalid.',403);return$job;}
 public function execute(string$authorization,array$args):array {
  $auth=$this->authorize($authorization,'research:execute');$job=$this->lease($auth,$args);$db=$this->os->store->db;$q=$db->prepare('SELECT * FROM life_opportunity_agent_execution WHERE job_id=?');$q->execute([$job['id']]);$existing=$q->fetch(PDO::FETCH_ASSOC);if($existing){if(!hash_equals($existing['token_hash'],$auth['token_hash'])||!hash_equals($existing['lease_hash'],$job['lease_hash']))throw new LifeError('This execution belongs to a different worker lease.',403);if($existing['status']==='completed')return array_replace(json_decode($existing['response_json'],true,64,JSON_THROW_ON_ERROR),['duplicate'=>true]);throw new LifeError('This research execution is already running or needs owner review.',409);}if($job['status']!=='leased'||$job['lease_until']<=$this->at())throw new LifeError('Research lease expired.',409);
  $this->transaction(function()use($auth,$job,$db){$key=hash('sha256',$auth['tenant_id'].':'.$this->day());$q=$db->prepare('SELECT reserved FROM life_opportunity_agent_budget WHERE id=?');$q->execute([$key]);$reserved=$q->fetchColumn();if($reserved===false){$db->prepare('INSERT INTO life_opportunity_agent_budget VALUES (?,?,?,0)')->execute([$key,$auth['tenant_id'],$this->day()]);}$u=$db->prepare('UPDATE life_opportunity_agent_budget SET reserved=reserved+? WHERE id=? AND reserved+?<=25');$u->execute([(int)$job['max_prospects'],$key,(int)$job['max_prospects']]);if($u->rowCount()!==1)throw new LifeError('The daily25-prospect research limit has been reached.',429);$db->prepare('INSERT INTO life_opportunity_agent_execution VALUES (?,?,?,?,?,?,?)')->execute([$job['id'],$auth['tenant_id'],$auth['token_hash'],$job['lease_hash'],'running','',$this->at()]);});
  try{$policy=self::jobPolicy($db,$job['id']);$context=[];if(($args['usePrivateContext']??false)===true||($policy['usePrivateContext']??false)===true){self::requireScope($db,$auth,'context:use');require_once __DIR__.'/opportunity-private-context.php';$context=(new LifeOpportunityPrivateContext($this->os,$this->clock))->forResearch($auth['token_hash'],$args);}require_once __DIR__.'/opportunity-ai.php';$target=null;if(($policy['opportunityId']??'')!==''){$state=$this->os->read()['state'];$o=LifeApplications::find($state,'opportunities',$policy['opportunityId']);$c=LifeApplications::find($state,'companies',$o['companyId']);$target=['company'=>$c,'opportunity'=>$o];$job['query_text']='Research only this existing company and role; do not discover unrelated prospects. Company data: '.json_encode(['name'=>$c['name'],'website'=>$c['website']??'','role'=>$o['title']]).'. User focus: '.$job['query_text'];if($context)$context['emails']=array_values(array_filter($context['emails']??[],fn($m)=>$m['opportunityId']===$o['id']));}$result=(new LifeOpportunityAI($this->os,$this->transport))->discover($job,$context);if($target){foreach($result['proposals']as&$p){$sameName=self::normal($p['company']['name'])===self::normal($target['company']['name']);$sameWebsite=!empty($p['company']['website'])&&!empty($target['company']['website'])&&self::website($p['company']['website'])===self::website($target['company']['website']);if(!$sameName&&!$sameWebsite)throw new LifeError('Research did not match the selected company. No tracking changes were made.',503);$p['company']['name']=$target['company']['name'];$p['role']=$target['opportunity']['title'];}unset($p);}$stored=(new LifeOpportunityAgents($this->os,$this->clock))->result($authorization,['jobId'=>$job['id'],'leaseToken'=>$args['leaseToken'],'proposals'=>$result['proposals']],true);$response=$stored+['proposals'=>$result['proposals'],'notice'=>'Research finished using Life’s private Gemini connection. No email was sent.'];}catch(Throwable$e){$error=$e instanceof LifeError?$e->getMessage():'Ramble could not finish this research. No tracking records were changed.';$code=$e instanceof LifeError?$e->status:503;$response=['jobId'=>$job['id'],'status'=>'failed','error'=>$error,'code'=>$code,'proposals'=>[]];try{(new LifeOpportunityAgents($this->os,$this->clock))->result($authorization,['jobId'=>$job['id'],'leaseToken'=>$args['leaseToken'],'error'=>$error],true);}catch(Throwable){}}
  $db->prepare('UPDATE life_opportunity_agent_execution SET status=?,response_json=? WHERE job_id=? AND token_hash=?')->execute(['completed',json_encode($response,JSON_THROW_ON_ERROR),$job['id'],$auth['token_hash']]);return$response;
 }
 public function apply(string $authorization,array $args):array {
  $auth=$this->authenticate($authorization);foreach(['company:write','opportunity:write','research:write']as$scope)self::requireScope($this->os->store->db,$auth,$scope);$jobId=LifeApplications::id($args['jobId']??'');$db=$this->os->store->db;$q=$db->prepare('SELECT * FROM life_opportunity_agent_jobs WHERE id=? AND tenant_id=?');$q->execute([$jobId,$auth['tenant_id']]);$job=$q->fetch(PDO::FETCH_ASSOC);if(!$job)throw new LifeError('Research result unavailable.',404);if(!in_array($job['status'],['completed','reviewed'],true)||$job['result_json']==='')throw new LifeError('Wait for a completed research result.',409);$policy=self::jobPolicy($db,$jobId);if(($policy['autoApply']??false)!==true)throw new LifeError('This job was queued for research only. Save reviewed results as the owner.',403);$payload=json_decode($job['result_json'],true,64,JSON_THROW_ON_ERROR);$proposals=LifeOpportunityAgents::proposals($payload['proposals']??[],(int)$job['max_prospects']);foreach($proposals as$p)if($p['contacts'])self::requireScope($db,$auth,'contact:write');$key=hash('sha256',$auth['tenant_id'].':apply:'.$jobId);$fingerprint=hash('sha256',$auth['token_hash'].':'.$jobId.':'.$job['result_hash']);
  return$this->transaction(function()use($authorization,$auth,$job,$jobId,$proposals,$db,$key,$fingerprint){$q=$db->prepare('SELECT fingerprint,response_json FROM life_opportunity_agent_receipts WHERE id=?');$q->execute([$key]);$receipt=$q->fetch(PDO::FETCH_ASSOC);if($receipt){if(!hash_equals($receipt['fingerprint'],$fingerprint))throw new LifeError('This research result was already applied by a different worker grant.',409);return json_decode($receipt['response_json'],true,64,JSON_THROW_ON_ERROR)+['duplicate'=>true];}$sequence=0;$save=function(string$operation,array$record)use($authorization,$jobId,&$sequence){return$this->write($authorization,['operation'=>$operation,'args'=>$record,'version'=>$this->os->read()['version'],'requestId'=>'apply-'.$jobId.'-'.(++$sequence)]);};$ids=[];
   foreach($proposals as$p){$s=$this->os->read()['state'];$companyFields=array_merge($p['company'],$p['notes']);$company=$this->duplicate('company',$companyFields,$s);    if($company){$missing=[];foreach($companyFields as$f=>$value)if($f!=='name'&&is_string($value)&&$value!==''&&empty($company[$f]))$missing[$f]=$value;if($missing)$save('company.save',['id'=>$company['id']]+$missing);$companyId=$company['id'];}else$companyId=$save('company.save',$companyFields)['recordId'];
    $opportunity=['companyId'=>$companyId,'pipeline'=>$job['pipeline'],'title'=>$p['role'],'stage'=>$job['pipeline']==='ai-testing'?'pending':'researched'];$opportunityId=$save('opportunity.save',$opportunity)['recordId'];
    foreach($p['contacts']as$contact){$record=['companyId'=>$companyId]+$contact;$old=$this->duplicate('contact',$record,$this->os->read()['state']);if(!$old)$save('contact.save',$record);else{$missing=[];foreach(['email','role','linkedin','sourceUrl']as$f)if(!empty($contact[$f])&&empty($old[$f]))$missing[$f]=$contact[$f];if($missing)$save('contact.save',['id'=>$old['id'],'emailEvidence'=>$contact['emailEvidence']]+$missing);}}
    foreach($p['sources']as$source)$save('research.save',['opportunityId'=>$opportunityId,'kind'=>'observation','category'=>'company','body'=>$source['claim'],'sourceUrl'=>$source['url']]);$ids[]=$opportunityId;
   }
   $result=['jobId'=>$jobId,'opportunityIds'=>array_values(array_unique($ids)),'saved'=>true,'requiresReview'=>true,'version'=>$this->os->read()['version'],'notice'=>'Research records updated with sources. Verified statuses and manual details were preserved. No outreach was sent.'];$db->prepare('INSERT INTO life_opportunity_agent_receipts VALUES (?,?,?,?,?)')->execute([$key,$auth['tenant_id'],$fingerprint,json_encode($result,JSON_THROW_ON_ERROR),$this->at()]);return$result;});
 }
 public function audit():array {$q=$this->os->store->db->prepare('SELECT id,operation,record_id,created_at FROM life_opportunity_agent_audit WHERE tenant_id=? ORDER BY created_at DESC LIMIT 100');$q->execute([$this->os->store->tenantId]);return['audit'=>$q->fetchAll(PDO::FETCH_ASSOC)];}
}
